<?php $payments=Db::all('SELECT * FROM payments WHERE order_id=? ORDER BY id DESC',[$o['id']]);$ip=setting('instapay_account');$link=setting('instapay_url');$wallet=setting('wallet_number');$canPay=in_array($o['status'],['quoted','payment_review'],true);$pending=false;foreach($payments as $p){if($p['status']==='pending'){$pending=true;}}$expired=strtotime($o['expires_at'].' UTC')<time(); ?>
<section class="page-hero container"><div class="eyebrow"><?= t('طلبك. خطوة بخطوة.','YOUR ORDER. STEP BY STEP.') ?></div><h1><?= e($o['code']) ?></h1><p><?= badge($o['status']) ?> · <?= e(localized($o)) ?> · <?= qty((int)$o['quantity_g']) ?></p></section><section class="container form-layout page-section"><div><article class="form-card"><h2><?= t('ملخص الطلب','Order summary') ?></h2><div class="quote-box"><div><span><?= t('المادة','Material') ?></span><b><?= money((int)$o['subtotal']) ?></b></div><div><span><?= t('النقل','Transport') ?></span><b><?= money((int)$o['shipping']) ?></b></div><div><span><?= t('رسوم حصاد','Hasad service fee') ?></span><b><?= money((int)$o['service_fee']) ?></b></div><div class="quote-total"><span><?= t('الإجمالي','Total') ?></span><strong><?= money((int)$o['total']) ?></strong></div></div><p><b><?= t('عنوان التسليم: ','Delivery address: ') ?></b><?= e(gov_label($o['governorate'])) ?> — <?= e($o['destination']) ?></p><?php if(in_array($o['status'],['paid','dispatching','delivered','refund_pending','refunded'],true)): ?><a class="button button-outline button-small" href="<?= e(url('invoice',['id'=>$o['id']])) ?>" target="_blank" rel="noopener"><?= t('بيان الطلب والسداد','Order & payment statement') ?></a><?php endif; ?><p class="caption"><?= $o['shipping_mode']==='hasad'?t('حصاد تنظم النقل.','Hasad arranges transport.'):t('المشتري ينظم النقل.','Buyer arranges transport.') ?></p></article>
<?php if($canPay): ?><article class="form-card stacked"><h2><?= t('١. حوّل المبلغ إلكترونياً','1. Make your online transfer') ?></h2><p><?= t('حوّل الإجمالي إلى إحدى الوجهات التالية. لا توجد مدفوعات نقدية على حصاد.','Transfer the total to one of the destinations below. Hasad does not accept cash payments.') ?></p><?php if($expired): ?><div class="note warning"><?= t('انتهت مهلة الحجز. تواصل مع الدعم لتأكيد الحجز قبل تحويل مبلغ جديد. لو حولت بالفعل، قدم بيانات التحويل للمراجعة.','The reservation period has ended. Contact support to confirm the hold before making a new transfer. If you already transferred, submit the details for review.') ?></div><?php endif; ?><?php if($ip!==''): ?><div class="payment-destination"><b>InstaPay</b><code dir="ltr"><?= e($ip) ?></code><button type="button" class="button button-outline button-small" data-copy="<?= e($ip) ?>" data-copy-label="<?= t('تم النسخ','Copied') ?>"><?= t('نسخ الحساب','Copy account') ?></button><?php if($link!==''): ?><a class="button button-green button-small" href="<?= e($link) ?>" target="_blank" rel="noopener noreferrer"><?= t('افتح InstaPay','Open InstaPay') ?></a><?php endif; ?></div><?php endif; ?><?php if($wallet!==''): ?><div class="payment-destination"><b><?= t('محفظة إلكترونية','Mobile wallet') ?></b><code dir="ltr"><?= e($wallet) ?></code><button type="button" class="button button-outline button-small" data-copy="<?= e($wallet) ?>" data-copy-label="<?= t('تم النسخ','Copied') ?>"><?= t('نسخ الرقم','Copy number') ?></button></div><?php endif; ?><div class="coming-soon"><span>Fawry / <?= t('فوري','Fawry') ?></span><span class="badge"><?= t('قريباً','Coming soon') ?></span></div><p class="caption"><?= t('فتح التطبيق أو تقديم إيصال لا يؤكد الدفع. المراجعة تتم من الحساب الفعلي.','Opening the app or submitting a receipt does not confirm payment. Staff verify the actual receiving account.') ?></p></article>
<?php if(!$pending): ?><form class="form-card stacked" method="post" enctype="multipart/form-data" action="<?= e(url('order',['id'=>$o['id']])) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="payment"><input type="hidden" name="order_id" value="<?= $o['id'] ?>"><h2><?= t('٢. سجّل بيانات التحويل','2. Submit transfer details') ?></h2><?php $methods=[];if($ip!==''){$methods['instapay']='InstaPay';}if($wallet!==''){$methods['wallet']=t('محفظة إلكترونية','Mobile wallet');}select_field(t('طريقة التحويل','Transfer method'),'method',$methods);field(t('مرجع العملية من التطبيق','Transaction reference from your app'),'reference','text','','required maxlength="100" dir="ltr"');field(t('المبلغ الذي حوّلته','Amount transferred'),'amount','number',number_format((int)$o['total']/100,2,'.',''),'required min="0.01" step="0.01" inputmode="decimal"');field(t('صورة الإيصال — اختياري، JPG أو PNG حتى ١٫٥ ميجابايت','Receipt image — optional, JPG or PNG up to 1.5 MB'),'proof','file','','accept="image/jpeg,image/png"'); ?><button class="button button-green button-full"><?= t('إرسال التحويل للمراجعة','Submit transfer for review') ?></button></form><?php else: ?><div class="note stacked"><?= icon('clock') ?><?= t('تحويلك قيد المراجعة. تابع حالة الطلب هنا.','Your transfer is under review. Follow the order status here.') ?></div><?php endif; ?><?php endif; ?>
<?php if($payments): ?><article class="form-card stacked"><h2><?= t('سجل التحويلات','Transfer history') ?></h2><?php foreach($payments as $p): ?><div class="record-line"><div><b><?= e($p['reference']) ?></b><p><?= money((int)$p['amount']) ?> · <?= e($p['method']) ?></p><?php if($p['review_note']): ?><small><?= e($p['review_note']) ?></small><?php endif; ?></div><?= badge($p['status']) ?></div><?php endforeach; ?></article><?php endif; ?></div><aside class="form-aside"><div class="aside-card"><h3><?= t('حالة الطلب','Order progress') ?></h3><ol class="tracking-list"><li><?= t('حجز الكمية وحفظ العرض','Reserve stock and save quote') ?></li><li><?= t('تقديم تحويل إلكتروني','Submit online transfer') ?></li><li><?= t('مراجعة وصول التحويل','Verify receipt of funds') ?></li><li><?= t('تنسيق النقل والتسليم','Coordinate transport and delivery') ?></li><li><?= t('تسوية مستحقات البائع','Settle the seller balance') ?></li></ol></div><div class="aside-card subtle"><h3><?= t('تحتاج مساعدة أو إلغاء؟','Need help or cancellation?') ?></h3><p><?= t('الإلغاء وتعديل الطلب يراجعهم فريق الإدارة. استخدم نموذج الدعم وسجل رقم طلبك.','Administrators review cancellation and change requests. Use the support form and include your order number.') ?></p><a class="button button-outline button-full" href="<?= e(url('contact',['order'=>$o['id']])) ?>"><?= t('تواصل مع الفريق','Contact the team') ?></a><a class="text-link" href="<?= e(url('account')) ?>"><?= t('كل طلباتي','All my orders') ?></a></div></aside></section>
